import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void negativeAndArrayUnchanged(){int[]a={-9,4,0,3};assertEquals(-2,TaskBinding.sum(a));assertArrayEquals(new int[]{-9,4,0,3},a);assertEquals(2147483647,TaskBinding.sum(2147483647,0));}}
